using FluentValidation;
namespace FintechApp.Requests.Sender { public class UpdateSenderRequest { public int SenderID { get; set; } public string Name { get; set; } = string.Empty; public string Mobile { get; set; } = string.Empty; public string GUID { get; set; } = string.Empty; public string Address { get; set; } = string.Empty; public int UserID { get; set; } public bool IsActive { get; set; } public bool IsOTPVerified { get; set; } public bool IsKYC { get; set; } public string KYCDocumentURL { get; set; } = string.Empty; public string IPAddress { get; set; } = string.Empty; public string Pincode { get; set; } = string.Empty; } public class UpdateSenderRequestValidator : AbstractValidator<UpdateSenderRequest> { public UpdateSenderRequestValidator() { RuleFor(x => x.SenderID).GreaterThan(0); } } }
